function IdolLive3D_SuperTimeLineState:__init()
end 



function IdolLive3D_SuperTimeLineState:__delete()
end




---@param idolLive3D_InteractiveManager_ table
---@param roleAnimator_ UnityEngine.Animator 
---@param timelineTFMaps_ table 
---@param interactiveState_ table  @ 对应 c# 中 IdolLive3D_SuperTimeline 这个 class
---@param stopCB_ function
function IdolLive3D_SuperTimeLineState:Init( idolLive3D_InteractiveManager_, roleAnimator_, timelineTFMaps_, interactiveState_, stopCB_ )

    self.idolLive3D_InteractiveManager = idolLive3D_InteractiveManager_
    self.idolLive3D_CameraEnv = idolLive3D_InteractiveManager_.idolLive3D_CameraEnv
    self.roleAnimator = roleAnimator_
    self.interactiveState = interactiveState_
    self.stopCB = stopCB_
    assert( isNotNull(self.stopCB) )
    self.currentClipId = nil

    -- 客制 自由轨道相机 json
    for _,clip in pairs(self.interactiveState.clips) do
        if isNotNull(clip.customFreeTrack) and clip.customFreeTrack.isUse == true then            
            clip.customFreeTrack.freeTrackJson = IdolLive3D_Utils.LoadJsonSync( clip.customFreeTrack.freeTrackJsonPath ) -- 比如: "Presets/IdolLive3D/FreeTrack/test1.json"
            clip.customFreeTrack.freeCameraTrackNodeParamsManager = IdolLive3D_FreeCameraTrackNodeParamsManager.New(clip.customFreeTrack.freeTrackJsonFileName, clip.customFreeTrack.freeTrackJson ) 
        end
    end


    -- 本 superTimeline 指定的脚本:
    self.scriptEnv = nil
    if string.isEmpty( self.interactiveState.luaPath ) == false then 
        local path = "Game.IdolLive3D.Interactive.Customs." .. self.interactiveState.luaPath
        print( "SuperTimeLine 脚本: " .. tostring(path) )
        local Script = import(path) -- "Game.IdolLive3D.Interactive.Customs.SuperTimeline_10302150"
        self.scriptEnv = Script.New(self)
    end 

    self.timelineStateEnvMaps = {}
    for clipId,tf in pairs(timelineTFMaps_) do 
        local timelineEnv = IdolLive3D_TimeLineState.New( clipId, self.roleAnimator, tf)
        local clipJson = self:_FindClipJson(clipId)

        self.timelineStateEnvMaps[clipId] = timelineEnv 
    end
    ---
    self.isPlaying = false
    self.isInit = true
end



function IdolLive3D_SuperTimeLineState:Start()
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
end


function IdolLive3D_SuperTimeLineState:OnDestroy()

    if isNotNull(self.scriptEnv) then 
        self.scriptEnv:Delete()
    end 

    IdolLive3D_Utils.StopCoroutine(self.co_1)
    self.co_1 = nil

    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end




function IdolLive3D_SuperTimeLineState:Update()
    if self.isInit ~= true then 
        return
    end 
    if self.isPlaying ~= true then 
        return
    end 
    --- 
    local timelineStateEnv = self.timelineStateEnvMaps[self.currentClipId]
    local clipJson = self:_FindClipJson(self.currentClipId)
    ---
    timelineStateEnv:PlayUpdate()


    if isNotNull(self.scriptEnv) and type(self.scriptEnv.SelfUpdate) == "function" then 
        self.scriptEnv:SelfUpdate( clipJson, timelineStateEnv )

    else
        if clipJson.enterConditionType == IdolLive3D_States.TimelineNodeEnterConditionType.T_WithCondition then 
            -- 若为 Loop模式: 现在播放第一遍时就能被触发:
            if timelineStateEnv.play.loopInteger > 0 or timelineStateEnv.play.loopDecimal > 0.1 then 
                assert( isNotNull(self.scriptEnv) )
                if type(self.scriptEnv.CheckEachFrame) == "function" then 
                    self.scriptEnv:CheckEachFrame( clipJson, timelineStateEnv )
                end
            end 

        else
            --- None,Hold 模式就是唯一一遍尾后帧,
            if timelineStateEnv.play.loopInteger > 0 then 
                local nextClipInfosNum = table.count(clipJson.nextClipInfos)
                if nextClipInfosNum == 0 then

                    if isNotNull(self.scriptEnv) and type(self.scriptEnv.EndPLay) == "function" then 
                        self.scriptEnv:EndPLay( clipJson, timelineStateEnv )
                    else 
                        self:EndPLay()
                    end 
                    self.isPlaying = false

                elseif nextClipInfosNum == 1 then
                    print("无条件 跳入下一个 clip" )
                    local nextClipInfo = clipJson.nextClipInfos[1]
                    self:PlayClip( nextClipInfo.clipId, false )
                else 
                    printError("暂不支持在此情况下存在多个 nextClipInfos")
                end
            end 
        end 
    end   
end 




-- =====================================================================================================



function IdolLive3D_SuperTimeLineState:Play()
    if self.isInit ~= true then 
        return
    end
    print("进入 super timeline")

    if isNotNull(self.scriptEnv) and type(self.scriptEnv.StartPlay) == "function" then 
        self.scriptEnv:StartPlay()
    end 

    self.isPlaying = true
    self.currentClipId = nil
    self:PlayClip( self.interactiveState.firstClipId , true )
end



---@param clipId_ string 
---@param isFirstClip_ boolean
function IdolLive3D_SuperTimeLineState:PlayClip( clipId_, isFirstClip_ )

    local lastClipId = self.currentClipId -- cache
    self.currentClipId = clipId_
    local timelineStateEnv = self.timelineStateEnvMaps[self.currentClipId]
    local clipJson = self:_FindClipJson(clipId_)
    assert(isNotNull(clipJson))
    -------
    self.idolLive3D_InteractiveManager:PlayVideoSubtitle(clipJson.videoSubtitle) -- 播放字幕

    -- 登记本 clip 内的 音效
    self.idolLive3D_InteractiveManager:RegistSounds( clipJson, true, function()
        return timelineStateEnv.play
    end )

    --printError("play clip " .. tostring(clipId_))
    self.idolLive3D_InteractiveManager:AddToQueue( self.interactiveState, {clipId = clipId_, clipJson = clipJson} ) 


    if isNotNull(lastClipId) then 
        self:EndClip( lastClipId )
    end 

    -- Custom 自由轨道相机
    --printError(" 开始一个 clip = " .. tostring(self.currentClipId))
    if isNotNull(clipJson.customFreeTrack) and clipJson.customFreeTrack.isUse == true then 
        self.idolLive3D_CameraEnv.freeCameraMgr:SwitchFreeCamera_PosFree( 
            clipJson.customFreeTrack.freeTrackCenterPos, 
            clipJson.customFreeTrack.freeCameraActiveSpatialRange, 
            self.idolLive3D_CameraEnv:GetFreeCameraSpatialParams(), -- !! 具体机位会在 后面设置, 此时写个临时值
            clipJson.customFreeTrack.freeCameraTrackNodeParamsManager
        )
    end

    --
    if isFirstClip_ == true then 

        Events.Broadcast(IdolLive3D_States.EventStartPlaySuperTimelineClip, {clipJson = clipJson,       timelineStateEnv = timelineStateEnv})

        IdolLive3D_BaseParamsJsonData.HandleSceneNodes( clipJson.sceneNodes, true )
        
        self.idolLive3D_InteractiveManager:BeginTimeline_SimpleBlendMode( timelineStateEnv, self.interactiveState, clipJson.easeInBlendTime )
    else 
        local lastTimelineStateEnv = self.timelineStateEnvMaps[lastClipId]
        local lastClipJson = self:_FindClipJson(lastClipId)
        Events.Broadcast(IdolLive3D_States.EventEndPlaySuperTimelineClip,   {clipJson = lastClipJson,   timelineStateEnv = lastTimelineStateEnv})
        ---
        Events.Broadcast(IdolLive3D_States.EventStartPlaySuperTimelineClip, {clipJson = clipJson,       timelineStateEnv = timelineStateEnv})

        IdolLive3D_BaseParamsJsonData.HandleSceneNodes( lastClipJson.sceneNodes, false )
        IdolLive3D_BaseParamsJsonData.HandleSceneNodes(     clipJson.sceneNodes, true )
        
        lastTimelineStateEnv:Hide()

        self.idolLive3D_InteractiveManager:ToNextTimeline( timelineStateEnv, clipJson.easeInBlendTime, clipJson.initFreeCameraSpatialParams )
    end 
end



function IdolLive3D_SuperTimeLineState:EndPLay()

    self:EndClip( self.currentClipId )

    local timelineStateEnv = self.timelineStateEnvMaps[self.currentClipId]
    local clipJson = self:_FindClipJson(self.currentClipId)
    print(" 正式退出 super timeline -- Default")
    self.isPlaying = false
    Events.Broadcast(IdolLive3D_States.EventEndPlaySuperTimelineClip,   {clipJson = clipJson,   timelineStateEnv = timelineStateEnv})

    IdolLive3D_BaseParamsJsonData.HandleSceneNodes( clipJson.sceneNodes, false )

    timelineStateEnv:Hide()

    local blendTime = checkNumber(self.interactiveState.easeOutBlendTime)
    self.stopCB( timelineStateEnv.playableDirector, self.currentClipId, blendTime )
end 




function IdolLive3D_SuperTimeLineState:EndClip( lastClipId_ )
    --printError("结束上一个 clip = " .. tostring(lastClipId_) )
    assert( isNotNull(lastClipId_) )
    local clipJson = self:_FindClipJson(lastClipId_)
    if isNull(clipJson.customFreeTrack) or clipJson.customFreeTrack.isUse ~= true then 
        return
    end 
    -- 回到当前 idle 的 自由轨道相机
    --printError(" 回到 idle 的自由相机 ")
    self.idolLive3D_CameraEnv:OnSwitchIdle( self.interactiveState.fromState )
end




function IdolLive3D_SuperTimeLineState:_FindClipJson( clipId_ )
    for _,clip in pairs(self.interactiveState.clips) do 
        if clip.clipId == clipId_ then 
            return clip
        end 
    end
    return nil
end
 



return IdolLive3D_SuperTimeLineState
